#!/usr/bin/env bash
# Tests for scripts/write_firebase_config.sh (release safety: never ship a placeholder
# firebase_options.dart). Runs the script inside throw-away copies of the repo layout.
#   scripts/test_write_firebase_config.sh      (CI: android job)
set -euo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
repo="$(cd "$here/.." && pwd)"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
fails=0
n=0

# A file shaped like `flutterfire configure` output (values are made up).
real_options() {
  cat <<'DART'
// File generated by FlutterFire CLI.
// ignore_for_file: type=lint
import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart'
    show defaultTargetPlatform, kIsWeb, TargetPlatform;

class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    if (kIsWeb) {
      throw UnsupportedError('DefaultFirebaseOptions have not been configured for web');
    }
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      default:
        throw UnsupportedError('DefaultFirebaseOptions are not supported for this platform.');
    }
  }

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'AIzaSyExampleExampleExampleExample00000',
    appId: '1:123456789012:android:0a1b2c3d4e5f60718293a4',
    messagingSenderId: '123456789012',
    projectId: 'doodle-battle-prod',
    storageBucket: 'doodle-battle-prod.firebasestorage.app',
  );
}
DART
}

# new_tree <name> -> prints a fresh fake repo root with the script and a pubspec using Firebase
new_tree() {
  local t="$tmp/$1"
  mkdir -p "$t/scripts" "$t/app/lib" "$t/app/android/app"
  cp "$repo/scripts/write_firebase_config.sh" "$t/scripts/"
  printf 'dependencies:\n  firebase_core: ^4.0.0\n' > "$t/app/pubspec.yaml"
  echo "$t"
}

# expect <name> <0|1> <args...>: run the script in the current tree, check exit status
expect() {
  local name="$1" want="$2"; shift 2
  n=$((n + 1))
  local got=0 out
  out="$("$t/scripts/write_firebase_config.sh" "$@" 2>&1)" || got=1
  if [[ "$got" == "$want" ]]; then
    echo "ok   $name"
  else
    echo "FAIL $name (exit $got, want $want)"; echo "$out" | sed 's/^/     /'
    fails=$((fails + 1))
  fi
}

# 1. The committed placeholder (UI team) must be refused for releases.
t="$(new_tree placeholder)"
cp "$repo/app/lib/firebase_options.dart" "$t/app/lib/"
grep -q DOODLE_BATTLE_FIREBASE_PLACEHOLDER "$t/app/lib/firebase_options.dart" \
  || { echo "FAIL committed placeholder lost its marker"; fails=$((fails + 1)); }
expect "committed placeholder is refused (--require)" 1 --require
expect "committed placeholder is fine for CI (no --require)" 0

# 2. The placeholder without its comment lines (someone trimmed it) is still refused.
t="$(new_tree trimmed)"
grep -v '^//' "$repo/app/lib/firebase_options.dart" > "$t/app/lib/firebase_options.dart"
expect "placeholder without comments/marker is refused" 1 --require

# 3. The CI demo stub written by the script itself is refused for releases.
t="$(new_tree stub)"
expect "CI writes the demo stub when nothing exists" 0
grep -q DOODLE_BATTLE_FIREBASE_PLACEHOLDER "$t/app/lib/firebase_options.dart" \
  || { echo "FAIL CI stub has no marker"; fails=$((fails + 1)); }
expect "CI demo stub is refused (--require)" 1 --require
sed -i '/DOODLE_BATTLE_FIREBASE_PLACEHOLDER/d' "$t/app/lib/firebase_options.dart"
expect "CI demo stub without marker is refused (demo- project id)" 1 --require

# 4. Missing file with --require.
t="$(new_tree missing)"
expect "missing firebase_options.dart is refused (--require)" 1 --require

# 5. A real (flutterfire-shaped) file passes, from the checkout or from the secret.
t="$(new_tree real)"
real_options > "$t/app/lib/firebase_options.dart"
expect "real config in the checkout passes" 0 --require
t="$(new_tree secret)"
FIREBASE_OPTIONS_DART_B64="$(real_options | base64 -w0)" expect "real config from the secret passes" 0 --require

# 6. Real-looking file with a dummy app id / demo project is refused.
t="$(new_tree dummy-appid)"
real_options | sed "s/1:123456789012:android:0a1b2c3d4e5f60718293a4/1:000000000000:android:0000000000000000000000/" \
  > "$t/app/lib/firebase_options.dart"
expect "all-zero Android appId is refused" 1 --require
t="$(new_tree demo-project)"
real_options | sed "s/projectId: 'doodle-battle-prod'/projectId: 'demo-something'/" > "$t/app/lib/firebase_options.dart"
expect "demo- project id is refused" 1 --require
t="$(new_tree marker-in-real)"
{ real_options; echo "// DOODLE_BATTLE_FIREBASE_PLACEHOLDER"; } > "$t/app/lib/firebase_options.dart"
expect "marker anywhere is refused" 1 --require

echo "write_firebase_config tests: $((n - fails))/$n passed"
(( fails == 0 ))
